example.code:
var obj = new { Name = "John Doe", Age = 32 };
var output = HumanReadableSerializer.Serialize(obj);
// Output:
// Name: John Doe
// Age: 32

var options = new HumanReadableSerializerOptions
{
    IncludeFields = true,
    DefaultIgnoreCondition = HumanReadableIgnoreCondition.WhenWritingNull,
};
var output = HumanReadableSerializer.Serialize(obj, options);

var doc = new HtmlDocument();
var comment = doc.CreateComment();
comment.Value = "This is a comment";
doc.BodyElement.AppendChild(comment);
// Output: <!-- This is a comment -->

// Load from file
var doc = new HtmlDocument();
doc.Load("page.html");

// Load from string
doc.LoadHtml("<html><body>Hello</body></html>");

// Query elements using XPath
var title = doc.SelectSingleNode("//title")?.InnerText;
var links = doc.SelectNodes("//a[@href]");

// Modify and save
doc.HtmlElement.SetAttributeValue("lang", "en");
doc.Save("modified.html");
